"""The dashboard JSON is generated by dashboard/build_dashboard.py; its datasets read only the demo tables."""
import importlib.util
import json
import re
from pathlib import Path

import yaml

DEMO = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("build_dashboard", DEMO / "dashboard" / "build_dashboard.py")
builder = importlib.util.module_from_spec(spec)
spec.loader.exec_module(builder)

DEMO_TABLES = {"audit", "principals", "demo_signals"}


def _tables(sql: str) -> set[str]:
    sql = re.sub(r"'[^']*'", "''", sql)
    return {t for t in re.findall(r"\b(?:FROM|JOIN)\s+([`\w.]+)", sql, flags=re.I) if t.upper() != "VALUES"}


def test_dashboard_up_to_date():
    assert builder.main(["--check"]) == 0, "run: uv run --frozen python dashboard/build_dashboard.py"


def test_datasets_reference_demo_tables():
    for name, sql in builder.DATASETS.items():
        assert "some_catalog" not in sql and "databricks_audit_demo" not in sql, name
        assert "system." not in sql and "__lakewatch" not in sql, name
        ctes = set(re.findall(r"\b(\w+)\s+AS\s*\(", sql, flags=re.I))
        tables = _tables(sql) - ctes
        assert tables, name
        assert tables <= DEMO_TABLES, (name, tables - DEMO_TABLES)


def test_time_windows_are_relative_to_the_data():
    for name, sql in builder.DATASETS.items():
        assert "current_timestamp" not in sql.lower() and "now()" not in sql.lower(), name
        assert "max(event_time)" in sql.lower(), name


def test_signals_are_deduplicated_and_from_the_last_reset():
    readers = [n for n, sql in builder.DATASETS.items() if "demo_signals" in sql]
    assert len(readers) >= 4
    for name in readers:
        sql = builder.DATASETS[name]
        assert re.search(r"GROUP BY rule, actor, event_time", sql), name
        # Signals created after the last load: the anchor is max(event_time) of the audit table.
        assert "anchor AS (SELECT max(event_time) AS t FROM audit)" in sql, name
        assert "WHERE created_at >= anchor.t" in sql, name


def test_parameters_have_display_name():
    for ds in builder.build()["datasets"]:
        for p in ds.get("parameters", []):
            assert p.get("displayName"), (ds["name"], p)


def test_widget_fields_match_encodings():
    for page in builder.build()["pages"]:
        for item in page["layout"]:
            widget = item["widget"]
            spec = widget.get("spec", {})
            wt = spec.get("widgetType", "")
            if wt.startswith("filter"):
                qnames = {q["name"] for q in widget["queries"]}
                assert {f["queryName"] for f in spec["encodings"]["fields"]} <= qnames, widget["name"]
                continue
            if not wt:
                continue
            names = {f["name"] for q in widget["queries"] for f in q["query"].get("fields", [])}
            enc = spec["encodings"]
            if "fields" in enc or "columns" in enc:
                used = {f["fieldName"] for f in enc.get("fields") or enc.get("columns")}
            else:
                used = {e["fieldName"] for e in enc.values() if isinstance(e, dict) and "fieldName" in e}
            assert used and used <= names, (widget["name"], used - names)


def test_layout_rows_fill_the_grid():
    for page in builder.build()["pages"]:
        assert page["layoutVersion"] == "GRID_V1"
        cells: dict[int, int] = {}
        for item in page["layout"]:
            p = item["position"]
            assert p["x"] + p["width"] <= 12, item["widget"]["name"]
            for y in range(p["y"], p["y"] + p["height"]):
                cells[y] = cells.get(y, 0) + p["width"]
        assert all(v == 12 for v in cells.values()), (page["name"], cells)


def test_h6b_chain_is_derived_from_the_hunt():
    text = (DEMO / "hunts" / "h6_staged_intrusion.sql").read_text()
    cell = next(c for c in text.split("-- COMMAND ----------") if c.lstrip().startswith("-- 6b."))
    hunt = cell[cell.index("WITH ev AS"):].strip()
    expected = re.sub(r"IDENTIFIER\('`' \|\| :catalog \|\| '`\.`' \|\| :schema \|\| '`\.`(\w+)`'\)", r"\1", hunt)
    sql = builder.DATASETS["ds_h6b_chain"]
    assert expected in sql
    assert "MATCH_RECOGNIZE" in sql and "PARTITION BY src_ip" in sql
    assert "IDENTIFIER" not in sql and ":catalog" not in sql and ":schema" not in sql


def test_page2_parameters():
    board = builder.build()
    params = {ds["name"]: [p["keyword"] for p in ds.get("parameters", [])] for ds in board["datasets"]}
    for name in ("ds_actions", "ds_actor_signals", "ds_h6b_chain"):
        assert params[name] == ["actor", "ip"], name
    for name in ("ds_signals", "ds_timeline", "ds_contrast"):
        assert params[name] == [], name  # page 1 is not filtered
    # The cap applies after the filter, inside the same query.
    actions = builder.DATASETS["ds_actions"]
    assert actions.index(":actor") < actions.index("LIMIT 20000")


def test_bundle_resource_points_at_the_json():
    res = yaml.safe_load((DEMO / "resources" / "dashboard.yml").read_text())
    dash = res["resources"]["dashboards"]["databricks_audit_dashboard"]
    assert (DEMO / "resources" / dash["file_path"]).resolve() == builder.OUT.resolve()
    assert dash["dataset_catalog"] == "${var.catalog}"
    assert dash["dataset_schema"] == "${resources.schemas.databricks_audit_demo.name}"
    assert dash["warehouse_id"] == "${var.warehouse_id}"
    json.loads(builder.OUT.read_text())
